import json

if not _items:
    raise ValueError("Baserow returned no cover-letter prompt records.")


def fields_of(item):
    data = item.get("json", {})
    nested = data.get("fields")
    return nested if isinstance(nested, dict) else data


def get_value(fields, names):
    for name in names:
        if name in fields and fields[name] is not None:
            return fields[name]
    return None


def scalar(value):
    # Baserow single-select fields can be returned as objects.
    if isinstance(value, dict):
        for key in ("value", "name"):
            nested = value.get(key)
            if nested is not None:
                return nested
        return value.get("id")

    if isinstance(value, list) and len(value) == 1:
        return scalar(value[0])

    return value


def is_enabled(value):
    value = scalar(value)

    if isinstance(value, bool):
        return value

    if isinstance(value, (int, float)):
        return value == 1

    if isinstance(value, str):
        return value.strip().lower() in (
            "true",
            "1",
            "yes",
            "enabled",
        )

    return False


def normalize_output_structure(value, prompt_key):
    value = scalar(value)

    if isinstance(value, dict):
        schema = value
    elif isinstance(value, str) and value.strip():
        try:
            schema = json.loads(value)
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Prompt '{prompt_key}' has invalid JSON in Output Structure."
            ) from exc
    else:
        raise ValueError(
            f"Prompt '{prompt_key}' has no Output Structure JSON Schema."
        )

    if not isinstance(schema, dict):
        raise ValueError(
            f"Prompt '{prompt_key}' Output Structure must be a JSON object."
        )

    if schema.get("type") != "object":
        raise ValueError(
            f"Prompt '{prompt_key}' Output Structure must define an object schema."
        )

    properties = schema.get("properties")
    if not isinstance(properties, dict) or not properties:
        raise ValueError(
            f"Prompt '{prompt_key}' Output Structure must define properties."
        )

    return json.dumps(
        schema,
        ensure_ascii=False,
        separators=(",", ":"),
    )


records = []

for item in _items:
    fields = fields_of(item)

    prompt_key = scalar(
        get_value(fields, ["Prompt Key", "Key", "prompt_key"])
    )
    if not isinstance(prompt_key, str):
        continue

    prompt_key = prompt_key.strip()
    if prompt_key != "cover_letter_generation":
        continue

    enabled = get_value(fields, ["Enabled", "enabled"])
    status = scalar(get_value(fields, ["Status", "status"]))

    if not is_enabled(enabled):
        continue

    if not isinstance(status, str) or status.strip() != "Active":
        continue

    template = scalar(
        get_value(
            fields,
            ["Prompt Template", "Prompt", "Template", "prompt_template"],
        )
    )
    version = scalar(
        get_value(fields, ["Version", "Prompt Version", "version"])
    )
    temperature = scalar(
        get_value(fields, ["Temperature", "temperature"])
    )
    output_structure = get_value(
        fields,
        [
            "Output Structure",
            "Output Schema",
            "output_structure",
            "output_schema",
        ],
    )

    if not isinstance(template, str) or not template.strip():
        raise ValueError(
            "Prompt 'cover_letter_generation' has no template."
        )

    try:
        version_value = float(version)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "Prompt 'cover_letter_generation' must have a numeric version."
        ) from exc

    try:
        temperature_value = float(temperature)
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "Prompt 'cover_letter_generation' must have a numeric temperature."
        ) from exc

    records.append(
        {
            "cover_letter_prompt_key": prompt_key,
            "cover_letter_prompt_version": version_value,
            "cover_letter_prompt_template": template.strip(),
            "cover_letter_temperature": temperature_value,
            "cover_letter_output_structure": normalize_output_structure(
                output_structure,
                prompt_key,
            ),
        }
    )

if not records:
    raise ValueError(
        "No enabled Active prompt found with Prompt Key "
        "'cover_letter_generation'."
    )

if len(records) > 1:
    raise ValueError(
        "More than one enabled Active prompt exists for "
        "'cover_letter_generation'."
    )

return [{"json": records[0]}]

import json
from datetime import datetime, timezone

if not _items:
    raise ValueError("The workflow received no merged input.")

data = _items[0]["json"]

company_name = data.get("company_name")
job_title = data.get("job_title")
job_description = data.get("job_description")
master_cv = data.get("master_cv")
template = data.get("cover_letter_prompt_template")

if not isinstance(company_name, str) or not company_name.strip():
    raise ValueError("company_name must be a non-empty string.")
if not isinstance(job_title, str) or not job_title.strip():
    raise ValueError("job_title must be a non-empty string.")
if not isinstance(job_description, str) or not job_description.strip():
    raise ValueError("job_description must be a non-empty string.")
if not isinstance(master_cv, dict):
    raise ValueError("master_cv must be an object.")
if not isinstance(template, str) or not template.strip():
    raise ValueError("Cover-letter prompt template is missing.")

date_value = data.get("date")
if not isinstance(date_value, str) or not date_value.strip():
    now = datetime.now(timezone.utc)
    date_value = now.strftime("%B ") + str(now.day) + now.strftime(", %Y")

compact_cv = json.dumps(
    master_cv,
    ensure_ascii=False,
    separators=(",", ":"),
)

prompt = template
replacements = {
    "[[date]]": date_value,
    "[[company_name]]": company_name.strip(),
    "[[job_title]]": job_title.strip(),
    "[[job_description]]": job_description.strip(),
    "[[master_cv_json]]": compact_cv,
}

for placeholder, value in replacements.items():
    prompt = prompt.replace(placeholder, value)

return [
    {
        "json": {
            **data,
            "cover_letter_date": date_value,
            "cover_letter_prompt": prompt,
        }
    }
]

import json


def extract_parsed(root):
    output = root.get("output")

    if isinstance(output, dict):
        return output

    if isinstance(output, str):
        try:
            parsed = json.loads(output)
        except json.JSONDecodeError as exc:
            raise ValueError(
                "Cover-letter output was not valid JSON after parsing."
            ) from exc

        if isinstance(parsed, dict):
            return parsed

    try:
        value = root["response"]["generations"][0][0]["text"]
    except (KeyError, IndexError, TypeError):
        value = None

    if isinstance(value, dict):
        return value

    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError as exc:
            raise ValueError(
                "Cover-letter output was not valid JSON after parsing."
            ) from exc

        if isinstance(parsed, dict):
            return parsed

    raise ValueError("Could not locate the parsed cover-letter output.")


if not _items:
    raise ValueError("The cover-letter model returned no items.")

parsed = extract_parsed(_items[0]["json"])

if not isinstance(parsed, dict):
    raise ValueError(
        "The cover-letter output must be a JSON object."
    )

paragraphs = parsed.get("paragraphs")
if not isinstance(paragraphs, list) or len(paragraphs) != 3:
    raise ValueError(
        "The model output must contain exactly three paragraphs."
    )

if any(
    not isinstance(paragraph, str) or not paragraph.strip()
    for paragraph in paragraphs
):
    raise ValueError(
        "Every cover-letter paragraph must be a non-empty string."
    )

normalized = {
    "paragraphs": [paragraph.strip() for paragraph in paragraphs],
}

return [
    {
        "json": {
            "cover_letter_response": json.dumps(
                normalized,
                ensure_ascii=False,
                separators=(",", ":"),
            )
        }
    }
]

